/**
 * B47 · Masthead — the hero, refused as imagery and rebuilt as type. One job:
 * open a public page with the claim, set in type.
 *
 * F11 refuses hero photography, illustration and 3D; A2 refuses the stock-photo
 * card. What is left is the thing a newspaper masthead always was: a claim, set
 * large, with nothing behind it. There is no image slot, no video slot and no
 * background slot, and adding one is a Book change rather than a prop.
 *
 * This is B1 PageHero's public-surface sibling and deliberately speaks its
 * vocabulary — title + titleSoft, one line of context, an actions cluster with
 * ONE primary — at display size on the wall instead of at 27px on the band. The
 * display steps exist for exactly this surface (firewall rule 17): the product
 * ramp tops out at the PageHero h1, so a marketing page had no honest way to
 * speak above the work.
 *
 * THE HEADER ANATOMY, and it is closed: a TITLE, ONE line under it, and ONE
 * or TWO buttons. Nothing above the title and nothing under the buttons.
 *
 * v0.8 adds ONE prop, `scale`, and it buys type and nothing else. `issue`
 * takes the STRUCTURE the Japanese editorial covers use — a title cut
 * condensed on the display face's width axis, set to the page's own edge,
 * over a deck in the ordinary UI voice. The anatomy above is untouched by
 * it: the cover is a way of setting the claim, not a licence to add to it.
 *
 * Don't: no kicker, eyebrow or category line above the title, and no mono note
 * under the actions — F12 refuses both by name, and the refusal is enforced by
 * the props not existing; no image, no video, no background of its own; no
 * second primary (B10 allows one per view region) and no third button; no
 * second sentence in the statement (running copy is B45 Prose); no stat inside
 * the Masthead (a number on the public surface is B50 ProofRow); no breadcrumb
 * anywhere near it (F13).
 */
import type { ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './masthead.css';

/**
 * THE HEADER ANATOMY IS CLOSED, and it is three things: a title, ONE line
 * under it, and one or two buttons. There is no kicker prop and no note prop,
 * and F12 refuses both by name — see the Don't list above. A slot that exists
 * is a slot that gets filled, so the refusal is the absent prop.
 */
export interface MastheadProps {
  /** The claim. Becomes the page's h1. */
  title: string;
  /** The claim's second half, receded — exactly PageHero's move. */
  titleSoft?: string;
  /** ONE sentence. Two is a paragraph, and a paragraph is B45 Prose. */
  statement?: string;
  /** ONE or TWO buttons, one of them primary. A third is a menu or a page. */
  actions?: ReactNode;
  align?: 'start' | 'center';
  /**
   * The TYPE, and only the type. `default` is what every page already
   * ships — display-1 in the UI face — and is byte-for-byte unchanged.
   *
   * `issue` is the cover treatment the Japanese editorial references set:
   * the same step in `--sv-font-display`, cut condensed on the face's WIDTH
   * axis, heavy, and flush to the container's edge, with the statement left
   * in the UI face at the ordinary step underneath it. THE CONTRAST IS THE
   * DEVICE — a display title over a plain deck is what a magazine does, and
   * setting the deck in the display face too would collapse the two voices
   * into one poster and lose the thing being borrowed.
   *
   * It is a SCALE and not a variant, which is the whole of its licence: it
   * changes type and nothing else. F11 still refuses the picture, F12 still
   * refuses the kicker and the note — the props do not exist at either
   * scale — and F14 still leaves the seed fill to the action. A scale that
   * started admitting slots would be a second component wearing this one's
   * name.
   *
   * ENGLISH ONLY, and the case is the CALLER's — see masthead.css, which
   * argues why `issue` does not force uppercase.
   */
  scale?: 'default' | 'issue';
  /** 1 by default — a page has one h1. 2 only when embedded in a page that already owns one. */
  headingLevel?: 1 | 2;
  className?: string;
}

export function Masthead({
  title,
  titleSoft,
  statement,
  actions,
  align = 'start',
  scale = 'default',
  headingLevel = 1,
  className,
}: MastheadProps) {
  /* One h1 per page (A4). Level 2 exists for the docs demo, where the page
     already owns its h1 and a second one would break the outline. */
  const Heading = headingLevel === 1 ? 'h1' : 'h2';

  return (
    /* start is the default because left-aligned type is how the rest of the
       system sets everything; centring is the exception a page asks for. */
    <header
      className={cx(
        'sv-masthead',
        align === 'center' && 'sv-masthead--center',
        /* The default scale adds NO class, so the element every existing
           page renders is the element it rendered before — the amendment
           is unreachable from a call site that does not ask for it. */
        scale === 'issue' && 'sv-masthead--issue',
        className,
      )}
    >
      {/* Nothing above the title. F12 refuses the mono kicker outright: it is
          a line of type that states the page's category to a reader who is
          already on the page, it pushes the claim down the sheet, and it is
          the single most reliable tell of a header nobody wrote. The claim
          opens the page. */}
      <Heading className="sv-masthead__title">
        {title}
        {/* Inside the heading, so the accessible name is the whole claim and
            not just its first half — with the space before it, exactly as
            PageHero writes it. */}
        {titleSoft && <span className="sv-masthead__title-soft"> {titleSoft}</span>}
      </Heading>
      {statement && <p className="sv-masthead__statement">{statement}</p>}
      {/* And nothing under the buttons. The mono line of terms, licences and
          counts that every generated landing page grows there is F12's other
          half: it is a footnote nobody asked for, in the metadata voice, doing
          the job the statement above already had. If a term is load-bearing it
          belongs in the statement or on the page the button opens. */}
      {actions && <div className="sv-masthead__actions">{actions}</div>}
    </header>
  );
}

/* B47 · Masthead — the claim, set large, with nothing behind it. */

@layer sv-components {
  /* The Masthead is NOT a card: no background, no shadow, no radius, no
     border. What sits behind the claim is the wall the page already paints,
     never paper — a surface here would turn the opening line of a public page
     into a widget, and the whole component exists because F11 refused the
     picture that used to go there. Horizontal room comes from the Sheet (B2),
     so this element sets the vertical measure and nothing else. Generous, and
     asymmetric: more air above the claim than below it, so the actions stay
     tied to the type rather than floating between it and the next block. */
  .sv-masthead {
    padding-top: calc(var(--sv-s8) * 2);
    padding-bottom: calc(var(--sv-s8) + var(--sv-s4));
  }


  /* Display-1 is the one step above the product's 27px h1 (rule 17). At 64px
     the UI defaults read loose and airy, so tracking and leading both close
     up; `balance` keeps a claim from ending on a single orphaned word, which
     is the whole reason it was set large. */
  .sv-masthead__title {
    font-size: var(--sv-display-1);
    font-weight: 800;
    line-height: 1.05;
    letter-spacing: -0.03em;
    text-wrap: balance;
  }

  /* PageHero's move, one surface up: the claim's second half recedes inside
     the same heading instead of breaking off into a line of its own. */
  .sv-masthead__title-soft {
    color: var(--sv-ink-soft);
  }

  /* Capped so it breaks like a deck and not like a paragraph — running copy
     at this width is B45 Prose, and this slot holds one sentence. */
  .sv-masthead__statement {
    max-width: 58ch;
    margin-top: var(--sv-s5);
    font-size: 17px;
    line-height: 1.55;
    color: var(--sv-ink-soft);
  }

  /* One primary, one ghost (B10). The row WRAPS rather than compressing, so a
     long label moves to the next line instead of becoming a clickable split
     across two.
     The buttons keep B10's registered geometry — 8/16 padding, 12.5/700 —
     and are NOT grown to meet the display type. A taller marketing button is
     a third button size the Book does not carry, and "the type above it is
     large" is not a reason the taxonomy accepts. */
  .sv-masthead__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sv-s3);
    margin-top: var(--sv-s7);
  }


  /* ---- scale="issue" · the cover ---------------------------------------
     The same claim, at the same step, in the third family — and the ONLY
     thing that changes is type. No picture arrives with it (F11), no kicker
     and no note (F12), and the seed fill stays the action's (F14). A scale
     that admitted a slot would be a second component wearing this one's
     name.

     THE FACE. `--sv-font-display` is legal in exactly three files (firewall
     rule 20) and this is one of them, because the display face exists so a
     public page can set a poster title — not so a screen can pick a voice.
     The statement below is deliberately NOT touched: it stays in the UI
     face at 17px, and the distance between a display title and a plain deck
     is the magazine device being borrowed. Set both in the display face and
     there is no contrast left to read.

     THE WIDTH AXIS, which is why this face and not a static one. Archivo
     carries `wdth` 62–125 (default 100) alongside `wght` 100–900. At full
     width the title is cut to `wdth` 78 — 22 points below normal on the 38
     that separate normal from the extreme, so most of the way there. That
     is far enough to read as a cut rather than as a normal face that
     happens to be bold: it buys close to a quarter more characters per
     line, so a claim that wrapped to three lines sets in two
     and the block squares up against the container's edge the way a cover
     does. It stops short of the extreme because past ~70 the counters at
     800 weight start closing into each other and a 64px line becomes
     texture rather than words.
     The weight does NOT move between the scales — 800 at both — so there is
     one axis in play and one reason for it.

     `font-variation-settings` rather than `font-stretch`: the high-level
     property only reaches the axis when the @font-face declares a
     `font-stretch` RANGE, and the weight-only Archivo subset does not, so
     `font-stretch: 78%` would be silently inert against it. The low-level
     property addresses the axis in the file directly. If the loaded file
     carries no `wdth` axis at all the declaration is inert too — but then
     the title simply sets at normal width and the page loses the cut and
     nothing else, which is the same way it degrades onto the fallback
     stack.

     UPPERCASE IS THE CALLER'S, and `issue` does not force it. The
     references are set in caps, but caps there are what the copywriter
     WROTE — and A3 governs copy, not this stylesheet. The system sets caps
     in one place only, the mono metadata voice, and a `text-transform` here
     would be the second: it would put a claim in the metadata register by
     accident. It also cannot know what it is shouting — a product name, an
     acronym, a proper noun that carries meaning in its case — and the
     tracking below is tuned for the mixed-case line the system actually
     sets, since caps at -0.035em jam. A caller who wants the cover's
     register types it in caps, and owns the consequence.

     THE EDGE. No inline padding at any scale — the Sheet (B2) owns the
     gutter — so the title already begins at the container's edge and this
     block adds nothing that would inset it. No optical negative margin
     either: the correction differs per face, and the moment Archivo has
     not loaded it would pull the claim a few pixels off the grid every
     other element on the page is aligned to.
     `text-wrap: balance` stays even though a balanced line does not run
     fully to the right edge: an orphaned last word on a 64px claim is a
     worse failure than a slightly short line, and it is the reason the
     claim was set large in the first place. */
  .sv-masthead--issue .sv-masthead__title {
    font-family: var(--sv-font-display);
    font-variation-settings: 'wdth' 78;
    /* 0.94 — inside the 0.92–0.95 the reference sets. A condensed face is
       narrower but no shorter, so the lines can close up until the
       descender of one nearly meets the cap of the next, and the title
       reads as a BLOCK of type rather than as stacked sentences. */
    line-height: 0.94;
    letter-spacing: -0.035em;
  }

  /* The deck's own step is unchanged; only the gap moves. 0.94 leading
     pulls the title's last baseline up, so the metric space below it reads
     shorter than it measures, and --sv-s5 after a 64px block looks like a
     caption rather than a deck. */
  .sv-masthead--issue .sv-masthead__statement {
    margin-top: var(--sv-s6);
  }

  /* Centring has to move the measure caps with the text, or the statement
     stays pinned to the left of a centred column and reads as a mistake.

     `align="center"` composes with `issue` and is supported, but it is the
     wrong thing to ask for and this is the comment saying so: a masthead is
     a LEFT EDGE. The whole argument for the cover treatment is that the
     claim is set to the page's own edge and reads as a masthead rather than
     as a centred hero — centring it hands back exactly what was bought, and
     leaves a condensed, heavy display block floating in the middle of the
     sheet, which is the hero A2 refuses with better type. It is still
     honoured, because `align` is an existing prop and `scale` is a scale:
     silently ignoring what a call site asked for is a worse component than
     one that does the thing it was told. */
  .sv-masthead--center {
    text-align: center;
  }

  .sv-masthead--center .sv-masthead__statement {
    margin-inline: auto;
  }

  .sv-masthead--center .sv-masthead__actions {
    justify-content: center;
  }

  /* ---- The floor ----
     --sv-display-1 clamps to 34px here, and at 34px the -0.03em that steadied
     a 64px line starts closing the counters while 1.05 leading starts crowding
     descenders on a title that now wraps to three lines — so both relax back
     toward the product ramp, and the page degrades INTO the system. Actions
     become a full-width column: at 320px two buttons side by side are two
     half-buttons. Nothing is hidden and nothing scrolls (C7). */
  @media (max-width: 560px) {
    .sv-masthead {
      padding-top: calc(var(--sv-s8) + var(--sv-s5));
      padding-bottom: var(--sv-s8);
    }

    .sv-masthead__title {
      line-height: 1.12;
      letter-spacing: -0.02em;
    }

    /* The cover degrades on the WIDTH axis exactly as it does on the size
       one, and at the same threshold, because they are the same event:
       --sv-display-1 reaches its 34px floor at 531px, so by 560px the type
       is already down at the step the product ramp sets and there is
       nothing left for a second breakpoint to do.
       `wdth` goes back to 100 — all the way to normal, not part of the way.
       78 removes about a fifth of every counter's width; that is a cut the
       reader can spend at 64px and cannot at 34px, where a three-line
       claim in the same cut turns into a wall. The face ends at the same
       normal width the UI face has, which is the token's own argument in
       the other axis: the page degrades INTO the system, never out of it.
       Tracking and leading relax with it — -0.035em was steadying a wide
       64px line and closes counters at 34px, and 0.94 leading crowds
       descenders once the claim wraps to three lines. 1.05 stays tighter
       than the product ramp's 1.12: this is still a cover, just a small
       one. The three declarations have to be restated here rather than
       inherited from the block above, because the compound selector
       outranks it. */
    .sv-masthead--issue .sv-masthead__title {
      font-variation-settings: 'wdth' 100;
      line-height: 1.05;
      letter-spacing: -0.02em;
    }

    .sv-masthead__actions {
      flex-direction: column;
      align-items: stretch;
      margin-top: var(--sv-s6);
    }
  }
}
